package com.customservants.compatibility;

import com.customservants.ServantModelCache;
import java.awt.Color;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Outlines the servant geometry an NPC is actually drawn with.
 * <p>
 * {@link ModelOutlineRenderer}'s {@code Actor} overload reads {@code Actor#getModel()}, which is
 * always the vanilla mesh - substitution happens further down in {@link com.customservants.ServantDrawCallbacks} and
 * never changes what the API reports - so an NPC we swap gets outlined around a silhouette that is
 * not on screen. The {@link RuneLiteObject} overload is the one public entry point that outlines a
 * caller-supplied model, so a scratch object carries the posed servant model into it.
 * <p>
 * That object is never activated. It is a model carrier handed straight to the outline renderer,
 * never registered with the client, so it adds nothing to the scene and no clickbox of its own.
 * <p>
 * An NPC a partner plugin swaps is outlined around that partner's model the same way, posed by the
 * partner through {@link PartnerOutlines}, so only one plugin needs to draw the outlines.
 * <p>
 * The posed model is the client's shared transform buffer, valid only until the next
 * {@code applyTransformations} call. Handing it over is safe because
 * {@link ModelOutlineRenderer#drawOutline(RuneLiteObject, int, Color, int)} rasterises it
 * synchronously, before returning and before anything else can pose a model.
 */
@Singleton
public class ServantOutliner
{
	@Inject
	private Client client;

	@Inject
	private ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	private ServantModelCache modelCache;

	@Inject
	private PartnerOutlines partnerOutlines;

	// Built lazily and reused - creating one per frame would churn for no reason
	private RuneLiteObject carrier;

	/**
	 * Outlines the servant or partner model an NPC is drawn with, matching what
	 * {@link ModelOutlineRenderer#drawOutline(net.runelite.api.Actor, int, Color, int)} would
	 * produce for the vanilla one.
	 *
	 * @return false when neither this plugin nor a partner swaps the NPC, leaving the caller to
	 * fall back to the vanilla outline
	 */
	boolean drawOutline(NPC npc, int outlineWidth, Color color, int feather)
	{
		// Posed first, so an NPC nobody swaps, the usual case, costs no location lookup. Nothing
		// below runs applyTransformations, so the shared posed model survives to the draw
		Model posed = modelCache.pose(npc);
		if (posed == null)
		{
			posed = partnerOutlines.pose(npc);
		}
		if (posed == null)
		{
			return false;
		}

		LocalPoint lp = npc.getLocalLocation();
		WorldView wv = npc.getWorldView();
		if (lp == null || wv == null)
		{
			return false;
		}

		if (carrier == null)
		{
			carrier = client.createRuneLiteObject();
		}

		carrier.setModel(posed);

		// The controller setters are used directly rather than setLocation, which would resolve a
		// tile height only for the footprint-aware one below to overwrite it
		carrier.setX(lp.getX());
		carrier.setY(lp.getY());
		carrier.setWorldView(lp.getWorldView());
		carrier.setLevel(wv.getPlane());

		// Mirrors what the Actor overload computes. Using the plain tile height instead would leave
		// a multi-tile NPC outlined above or below where it is drawn.
		carrier.setZ(Perspective.getFootprintTileHeight(client, lp, wv.getPlane(), npc.getFootprintSize())
			- npc.getAnimationHeightOffset());
		carrier.setOrientation(npc.getCurrentOrientation());

		// Projects and rasterizes the model before returning, which is what makes handing it the
		// shared transform buffer from pose() safe
		modelOutlineRenderer.drawOutline(carrier, outlineWidth, color, feather);
		return true;
	}

	/**
	 * Drops the scratch object, releasing its reference to a posed model, which may be a partner's.
	 */
	public void clear()
	{
		carrier = null;
	}
}

